{
  "summary": "Acme Cloud Services proposes a 12-month renewal with a 12% price increase; gather contract terms, renewal/pricing policy, SLA performance, and invoice history to craft a fact-based counter-response before renewal decision.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (end date, pricing terms, renewal/notice clauses, price-increase caps), any internal vendor renewal/procurement policy documents, recent invoices from Acme, and SLA performance records for the contract period; run the SLA credit calculator to determine any SLA misses and credits owed to us.",
      "why": "The executor needs the exact contract terms, applicable policy limits on price increases, invoice/billing history, and any SLA credits owed to draft an accurate, defensible reply to the 12% increase request."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the reply to Acme Cloud Services acknowledging the renewal request, referencing the contract end date and terms, noting any SLA credits owed to us that should offset costs, and proposing a counter (e.g., accept, negotiate a lower increase, or apply SLA credits against the increase) based on the facts gathered.",
      "why": "The executor synthesizes the retrieved contract, policy, SLA, and invoice facts into the final vendor-facing response for human review and approval."
    }
  ],
  "escalate":
